  "imk.s.eu_enrol": ["Enrolment application", "Заявка на зачисление", "Oʻqishga qabul arizasi", "Solicitud de matrícula", "Einschreibungsantrag", "注册申请"],
  "imk.s.eu_preenrol": ["Pre-enrolment request", "Заявка на предзачисление", "Dastlabki roʻyxatga olish arizasi", "Solicitud de preinscripción", "Vorimmatrikulation", "预注册申请"],
